window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cebac1a30d78502e"]={"versions": [{"id": "FIG-cebac1a30d78502e", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Manifest-Spezifikation (Adaptive Platform). Das Diagramm spezifiziert das Metamodell zur Referenzierung eines <code>DataPrototype</code> im Kontext eines <code>CompositionSwComponentType</code>, wobei die Typisierung über einen <code>ApplicationDataType</code> oder einen <code>ImplementationDataType</code> erfolgen kann.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und zwei Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>CompositionDataPrototypeRef</code>: Zentrale Metaklasse mit dem Attribut <code>+ tlvDataId : PositiveInteger [0..1]</code>.</li>\n<li><code>DataPrototypeInSwComponentTypeInstanceRef</code> (gekennzeichnet mit Stereotyp/Schlüsselwort <code>AtpInstanceRef</code>): Über die Kompositionsrolle <code>+dataPrototype</code> mit Multiplizität <code>0..1</code> angebunden.</li>\n<li><code>ElementInImplementationDatatypeInstanceRef</code>: Über die Kompositionsrolle <code>+elementInImplDatatype</code> mit Multiplizität <code>0..1</code> angebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Instanzreferenzen modellieren Navigationspfade zur Adressierung von Datenprototypen innerhalb geschachtelter Software-Komponentenstrukturen sowie tieferliegender Elemente von Implementierungsdatentypen zur Entwurfs- bzw. Konfigurationszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Vorgabe für Manifest-Modelle der AUTOSAR Adaptive Platform. Eine <code>CompositionDataPrototypeRef</code> kann wahlweise eine Instanzreferenz auf einen Datenprototypen (<code>dataPrototype</code>) und/oder auf ein Element eines Implementierungsdatentyps (<code>elementInImplDatatype</code>) aggregieren. Das optionale Attribut <code>tlvDataId</code> dient der Vergabe einer spezifischen Daten-Identifikationsnummer (z. B. für TLV-Serialisierung im Kommunikationsmanifest).</p>"}, {"id": "FIG-dd50bf5cb15aa061", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Manifest-Spezifikation (Adaptive Platform). Das Diagramm spezifiziert das Metamodell zur Referenzierung eines <code>DataPrototype</code> im Kontext eines <code>CompositionSwComponentType</code>, wobei die Typisierung über einen <code>ApplicationDataType</code> oder einen <code>ImplementationDataType</code> erfolgen kann.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und zwei Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>CompositionDataPrototypeRef</code>: Zentrale Metaklasse ohne eigene Attribute.</li>\n<li><code>DataPrototypeInSwComponentTypeInstanceRef</code> (gekennzeichnet mit Stereotyp/Schlüsselwort <code>AtpInstanceRef</code>): Über die Kompositionsrolle <code>+dataPrototype</code> mit Multiplizität <code>0..1</code> angebunden.</li>\n<li><code>ElementInImplementationDatatypeInstanceRef</code>: Über die Kompositionsrolle <code>+elementInImplDatatype</code> mit Multiplizität <code>0..1</code> angebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Instanzreferenzen modellieren Navigationspfade zur Adressierung von Datenprototypen innerhalb geschachtelter Software-Komponentenstrukturen sowie tieferliegender Elemente von Implementierungsdatentypen zur Entwurfs- bzw. Konfigurationszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Vorgabe für Manifest-Modelle der AUTOSAR Adaptive Platform. Eine <code>CompositionDataPrototypeRef</code> kann wahlweise eine Instanzreferenz auf einen Datenprototypen (<code>dataPrototype</code>) und/oder auf ein Element eines Implementierungsdatentyps (<code>elementInImplDatatype</code>) aggregieren, um Datenelemente im Kontext zusammengesetzter Komponentenstrukturen eindeutig zu referenzieren.</p>"}], "trans": [{"from": "FIG-cebac1a30d78502e", "to": "FIG-dd50bf5cb15aa061", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In Klasse <code>CompositionDataPrototypeRef</code> wurde das Attribut <code>+ tlvDataId : PositiveInteger [0..1]</code> entfernt.</li>\n</ul>"}]};
